INSERT INTO research_sites (id, name, url, search_url, domains, coverage, record_types, access, source_quality, api, agent_notes, enabled, sort, created_by, created_at, updated_at) VALUES
  ('freebmd', 'FreeBMD', 'https://www.freebmd.org.uk/', NULL, '["freebmd.org.uk"]', 'England and Wales civil registration index of births, marriages and deaths, 1837 to the 1990s (most complete before about 1990).', '["vital"]', 'open', 'indexes', 'No API.', 'An index only: it gives the quarter, district, volume and page, not the certificate. Search is a form. Log the index entry and add a to-do to order the certificate from the General Register Office.', 1, 10, 'seed', '2026-11-15T00:00:00.000Z', '2026-11-15T00:00:00.000Z'),
  ('freecen', 'FreeCEN', 'https://www.freecen.org.uk/', NULL, '["freecen.org.uk"]', 'Volunteer transcriptions of the 1841–1901 censuses of England, Wales and Scotland; coverage varies by county and year.', '["census"]', 'open', 'indexes', 'No API.', 'Coverage is partial: a nil result only means the household isn''t transcribed yet. Say which county and year were covered.', 1, 20, 'seed', '2026-11-15T00:00:00.000Z', '2026-11-15T00:00:00.000Z'),
  ('freereg', 'FreeREG', 'https://www.freereg.org.uk/', NULL, '["freereg.org.uk"]', 'Volunteer transcriptions of parish and nonconformist registers (baptisms, marriages, burials) for England, Wales and Scotland, mostly before 1837.', '["church"]', 'open', 'indexes', 'No API.', 'Transcriptions, not images. Check which registers and years a place has before treating a nil as negative evidence.', 1, 30, 'seed', '2026-11-15T00:00:00.000Z', '2026-11-15T00:00:00.000Z'),
  ('nara', 'U.S. National Archives Catalog (NARA)', 'https://catalog.archives.gov/', NULL, '["archives.gov"]', 'United States federal records: censuses, military service and pension files, passenger and naturalization records, land entry files; many digitised.', '["census","military","immigration","land"]', 'open', 'original-images', 'National Archives Catalog API (v2); needs a free API key from NARA.', 'Search the catalog by name for digitised files and by series for unindexed ones. Many genealogy series are indexed only on partner sites; if so, name the series in a to-do.', 1, 40, 'seed', '2026-11-15T00:00:00.000Z', '2026-11-15T00:00:00.000Z'),
  ('tna-discovery', 'The National Archives (UK) Discovery', 'https://discovery.nationalarchives.gov.uk/', NULL, '["nationalarchives.gov.uk"]', 'Catalogue of The National Archives in Kew and of many other UK archives: military service, wills before 1858, immigration and naturalisation, and more.', '["military","probate","immigration","land"]', 'open', 'indexes', 'Discovery API (read-only, no key).', 'Many descriptions name individuals. Some digitised records are free to download, others are paid or only in partner collections: log those as inconclusive with the catalogue reference for the owner.', 1, 50, 'seed', '2026-11-15T00:00:00.000Z', '2026-11-15T00:00:00.000Z'),
  ('lac', 'Library and Archives Canada', 'https://library-archives.canada.ca/', NULL, '["library-archives.canada.ca","bac-lac.gc.ca"]', 'Canada: censuses 1825–1931, passenger lists, land petitions, First World War service files (fully digitised), naturalisation records.', '["census","immigration","military","land"]', 'open', 'original-images', 'No public genealogy API.', 'Use Collection Search with the person''s name and narrow by database. First World War personnel files are complete images.', 1, 60, 'seed', '2026-11-15T00:00:00.000Z', '2026-11-15T00:00:00.000Z'),
  ('naa', 'National Archives of Australia', 'https://www.naa.gov.au/', NULL, '["naa.gov.au"]', 'Australian government records: First World War service records (digitised), immigration and passenger records, naturalisation, alien registration.', '["military","immigration"]', 'open', 'original-images', 'No public API.', 'Search RecordSearch by name; many files are digitised and viewable. Files not yet digitised can be requested by the owner: add a to-do with the item barcode.', 1, 70, 'seed', '2026-11-15T00:00:00.000Z', '2026-11-15T00:00:00.000Z'),
  ('ape', 'Archives Portal Europe', 'https://www.archivesportaleurope.net/', NULL, '["archivesportaleurope.net"]', 'Finding aids from national and regional archives across Europe, with links to their own digitised records.', '["church","vital","land","probate"]', 'open', 'indexes', 'No public API.', 'A catalogue that leads to the holding archive''s own site; follow the link and cite the archive''s record, not the portal.', 1, 80, 'seed', '2026-11-15T00:00:00.000Z', '2026-11-15T00:00:00.000Z'),
  ('antenati', 'Antenati (Portale Antenati)', 'https://antenati.cultura.gov.it/', NULL, '["antenati.cultura.gov.it"]', 'Italy''s state archives: civil registration (births, marriages, deaths) from about 1809, and some earlier records, digitised; partly name-indexed.', '["vital","census"]', 'open', 'original-images', 'IIIF image manifests; no search API.', 'Most records are browse-only: find the archive, town, year and register, then the page. Records are in Italian or Latin. Cite archive, town, register, year and image number.', 1, 90, 'seed', '2026-11-15T00:00:00.000Z', '2026-11-15T00:00:00.000Z'),
  ('pares', 'PARES (Portal de Archivos Españoles)', 'https://pares.cultura.gob.es/', NULL, '["pares.cultura.gob.es","pares.mcu.es"]', 'Spain''s state archives, including emigration, military and colonial records (Archivo General de Indias); many digitised.', '["immigration","military","land"]', 'open', 'original-images', 'No public API.', 'Name search covers described items only. Spanish interface; parish and civil registers are mostly held locally, not here.', 1, 100, 'seed', '2026-11-15T00:00:00.000Z', '2026-11-15T00:00:00.000Z'),
  ('matricula', 'Matricula', 'https://data.matricula-online.eu/', NULL, '["matricula-online.eu"]', 'Digitised parish registers from dioceses in Austria, Germany, Poland, Slovenia and nearby countries.', '["church"]', 'open', 'original-images', 'No public API.', 'Images only, browsed by diocese, parish and register type; nothing is name-indexed. Cite parish, register, years and page.', 1, 110, 'seed', '2026-11-15T00:00:00.000Z', '2026-11-15T00:00:00.000Z'),
  ('digitalarkivet', 'Digitalarkivet (National Archives of Norway)', 'https://www.digitalarkivet.no/', NULL, '["digitalarkivet.no"]', 'Norway: censuses, church books, emigrant lists and probate, as images and searchable transcriptions.', '["census","church","immigration","probate"]', 'open', 'original-images', 'Has an open API for some datasets.', 'Transcribed sources are name-searchable; church books are mostly images to browse by parish.', 1, 120, 'seed', '2026-11-15T00:00:00.000Z', '2026-11-15T00:00:00.000Z'),
  ('riksarkivet', 'Riksarkivet (National Archives of Sweden)', 'https://sok.riksarkivet.se/', NULL, '["riksarkivet.se"]', 'Sweden: church books, household examination rolls, censuses and estate inventories, digitised and free.', '["church","census","probate"]', 'open', 'original-images', 'Has open APIs for some data.', 'Household examination rolls track a family year by year; cite parish, volume and page. Population registers are name-searchable for some years.', 1, 130, 'seed', '2026-11-15T00:00:00.000Z', '2026-11-15T00:00:00.000Z'),
  ('irishgenealogy', 'IrishGenealogy.ie', 'https://www.irishgenealogy.ie/', NULL, '["irishgenealogy.ie"]', 'Ireland: civil registration images (births over 100 years, marriages over 75, deaths over 50 years old) and some church records.', '["vital","church"]', 'open', 'original-images', 'No API.', 'Civil records link to the register image: read the image and cite it, not just the index line.', 1, 140, 'seed', '2026-11-15T00:00:00.000Z', '2026-11-15T00:00:00.000Z'),
  ('chronicling-america', 'Chronicling America (Library of Congress)', 'https://www.loc.gov/collections/chronicling-america/', NULL, '["loc.gov"]', 'Digitised United States newspapers, 1756–1963, with full-text search.', '["newspapers"]', 'open', 'original-images', 'loc.gov JSON API (no key).', 'OCR text is noisy: search names in several spellings and read the page image before citing. Cite paper, date, page and column.', 1, 150, 'seed', '2026-11-15T00:00:00.000Z', '2026-11-15T00:00:00.000Z'),
  ('trove', 'Trove (National Library of Australia)', 'https://trove.nla.gov.au/', NULL, '["trove.nla.gov.au","nla.gov.au"]', 'Digitised Australian newspapers (1803–1950s), government gazettes, books and directories.', '["newspapers"]', 'open', 'original-images', 'Trove API v3; needs a free personal API key.', 'Use quotation marks for exact names. Family notices (births, deaths, marriages) are a category of their own. Cite title, date and page.', 1, 160, 'seed', '2026-11-15T00:00:00.000Z', '2026-11-15T00:00:00.000Z'),
  ('papers-past', 'Papers Past (National Library of New Zealand)', 'https://paperspast.natlib.govt.nz/', NULL, '["paperspast.natlib.govt.nz"]', 'Digitised New Zealand newspapers, magazines, letters and parliamentary papers, 1839 onward.', '["newspapers"]', 'open', 'original-images', 'Searchable through the DigitalNZ API (free key).', 'Full-text search with date and region filters; read the page image to confirm OCR.', 1, 170, 'seed', '2026-11-15T00:00:00.000Z', '2026-11-15T00:00:00.000Z'),
  ('delpher', 'Delpher', 'https://www.delpher.nl/', NULL, '["delpher.nl"]', 'Digitised Dutch newspapers, books and periodicals from the 1600s onward.', '["newspapers"]', 'open', 'original-images', 'Has an API for registered users.', 'Search in Dutch; name variants and old spellings matter. Family announcements are common in newspapers.', 1, 180, 'seed', '2026-11-15T00:00:00.000Z', '2026-11-15T00:00:00.000Z'),
  ('gallica', 'Gallica (Bibliothèque nationale de France)', 'https://gallica.bnf.fr/', NULL, '["gallica.bnf.fr"]', 'France: digitised newspapers, books, directories and periodicals.', '["newspapers"]', 'open', 'original-images', 'Has SRU and IIIF APIs (no key).', 'Full-text search in the original language; check the page image. Civil and parish registers are on departmental archive sites, not here.', 1, 190, 'seed', '2026-11-15T00:00:00.000Z', '2026-11-15T00:00:00.000Z'),
  ('europeana', 'Europeana', 'https://www.europeana.eu/', NULL, '["europeana.eu"]', 'Aggregated digitised items from European libraries, archives and museums, including newspapers and documents.', '["newspapers","church"]', 'open', 'original-images', 'Europeana API; needs a free API key.', 'A discovery layer: follow each item to the holding institution and cite that.', 1, 200, 'seed', '2026-11-15T00:00:00.000Z', '2026-11-15T00:00:00.000Z'),
  ('findagrave', 'Find a Grave', 'https://www.findagrave.com/', 'https://www.findagrave.com/memorial/search?firstname={given}&lastname={surname}', '["findagrave.com"]', 'Volunteer-created memorials for graves worldwide, strongest in the United States; many with headstone photos.', '["graves"]', 'open', 'indexes', 'No public API.', 'A memorial is derivative; a headstone photo is better evidence than the transcription. Family links on memorials are compiled by volunteers: leads, not proof.', 1, 210, 'seed', '2026-11-15T00:00:00.000Z', '2026-11-15T00:00:00.000Z'),
  ('cwgc', 'Commonwealth War Graves Commission', 'https://www.cwgc.org/', NULL, '["cwgc.org"]', 'Commonwealth service personnel who died in the First and Second World Wars: burial or memorial place, unit, often next of kin.', '["military","graves"]', 'open', 'indexes', 'No public API.', 'Search Find War Dead by surname and initials; additional information often names parents or spouse, a strong identifier.', 1, 220, 'seed', '2026-11-15T00:00:00.000Z', '2026-11-15T00:00:00.000Z'),
  ('genuki', 'GENUKI', 'https://www.genuki.org.uk/', NULL, '["genuki.org.uk"]', 'A directory of genealogy resources for the UK and Ireland, organised by county and parish.', '["directory"]', 'open', 'compiled', 'No API.', 'Use it to find which registers, archives and transcriptions exist for a parish, not as a source to cite.', 1, 230, 'seed', '2026-11-15T00:00:00.000Z', '2026-11-15T00:00:00.000Z'),
  ('cyndislist', 'Cyndi''s List', 'https://www.cyndislist.com/', NULL, '["cyndislist.com"]', 'A categorised directory of genealogy websites, worldwide.', '["directory"]', 'open', 'compiled', 'No API.', 'A finding aid: use it to discover record sites for a place or topic, then search those sites.', 1, 240, 'seed', '2026-11-15T00:00:00.000Z', '2026-11-15T00:00:00.000Z'),
  ('internet-archive', 'Internet Archive', 'https://archive.org/', NULL, '["archive.org"]', 'Digitised books, city directories, county and parish histories, yearbooks, and microfilmed records; also the Wayback Machine for vanished pages.', '["census","church","newspapers","land"]', 'open', 'original-images', 'Open search and metadata APIs (no key).', 'Full-text search inside books works; cite the book, edition and page. Use the Wayback Machine to cite a page that has moved.', 1, 250, 'seed', '2026-11-15T00:00:00.000Z', '2026-11-15T00:00:00.000Z'),
  ('hathitrust', 'HathiTrust Digital Library', 'https://www.hathitrust.org/', NULL, '["hathitrust.org"]', 'Millions of digitised books and serials from research libraries: local histories, directories, genealogies, government documents.', '["compiled-trees","land"]', 'open', 'original-images', 'Bibliographic and data APIs (no key for the bibliographic API).', 'Search the full text; volumes still in copyright show only page numbers of hits. Published genealogies are compiled: leads, not proof.', 1, 260, 'seed', '2026-11-15T00:00:00.000Z', '2026-11-15T00:00:00.000Z'),
  ('dpla', 'Digital Public Library of America', 'https://dp.la/', NULL, '["dp.la"]', 'Aggregated digitised items from libraries, archives and museums across the United States.', '["newspapers","land"]', 'open', 'original-images', 'DPLA API; needs a free API key.', 'A discovery layer: follow each item to the holding institution and cite that.', 1, 270, 'seed', '2026-11-15T00:00:00.000Z', '2026-11-15T00:00:00.000Z'),
  ('worldcat', 'WorldCat', 'https://search.worldcat.org/', NULL, '["worldcat.org"]', 'The union catalogue of libraries worldwide: find which libraries hold a book, microfilm or periodical.', '["directory"]', 'open', 'compiled', 'WorldCat APIs for member libraries only.', 'Use it to locate a published source that isn''t online, then add a to-do for the owner naming the library.', 1, 280, 'seed', '2026-11-15T00:00:00.000Z', '2026-11-15T00:00:00.000Z'),
  ('familysearch', 'FamilySearch', 'https://www.familysearch.org/', 'https://www.familysearch.org/search/record/results?q.givenName={given}&q.surname={surname}', '["familysearch.org"]', 'Worldwide: billions of indexed records and digitised microfilm of civil, church, census, probate, land, military and migration records, strongest for the Americas and Europe, 1500s–1900s.', '["census","vital","church","military","immigration","land","probate","compiled-trees"]', 'free-account', 'original-images', 'Official API for registered developer partners only; not available with a personal key.', 'Search Historical Records, not Family Tree: tree profiles are compiled leads. Many images need sign-in; if a record shows only the index, cite it as an index. Use the catalog (by place) for unindexed films.', 1, 290, 'seed', '2026-11-15T00:00:00.000Z', '2026-11-15T00:00:00.000Z'),
  ('billiongraves', 'BillionGraves', 'https://billiongraves.com/', 'https://billiongraves.com/search/results?given_names={given}&family_names={surname}', '["billiongraves.com"]', 'GPS-tagged headstone photos and transcriptions, worldwide.', '["graves"]', 'free-account', 'original-images', 'No public API.', 'Every record has a headstone photo: read the stone, not only the transcription.', 1, 300, 'seed', '2026-11-15T00:00:00.000Z', '2026-11-15T00:00:00.000Z'),
  ('ellis-island', 'Statue of Liberty–Ellis Island Foundation passenger search', 'https://heritage.statueofliberty.org/', NULL, '["statueofliberty.org"]', 'Passenger arrivals at the Port of New York, 1820–1957, with manifest images.', '["immigration"]', 'free-account', 'original-images', 'No public API.', 'Transcribed names are often misspelled: try variants and search by town of origin. A free sign-in is needed to view manifests; read the full manifest line (both pages) before citing.', 1, 310, 'seed', '2026-11-15T00:00:00.000Z', '2026-11-15T00:00:00.000Z'),
  ('geneanet', 'Geneanet', 'https://www.geneanet.org/', NULL, '["geneanet.org"]', 'Compiled family trees, mostly European and strongest for France, plus indexed records and cemetery photos.', '["compiled-trees","graves"]', 'free-account', 'compiled', 'No public API.', 'Trees are compiled by users: leads only. Some search features need a premium account; log those as inconclusive.', 1, 320, 'seed', '2026-11-15T00:00:00.000Z', '2026-11-15T00:00:00.000Z'),
  ('scotlandspeople', 'ScotlandsPeople', 'https://www.scotlandspeople.gov.uk/', NULL, '["scotlandspeople.gov.uk"]', 'Scotland''s official records: statutory registers from 1855, old parish registers, censuses, wills and testaments.', '["vital","church","census","probate"]', 'subscription', 'original-images', 'No public API.', 'Pay-per-view: searching the index costs credits and images cost more. Without a credential, log as inconclusive and add a to-do for the owner naming the record type, year and district.', 1, 330, 'seed', '2026-11-15T00:00:00.000Z', '2026-11-15T00:00:00.000Z'),
  ('ancestry', 'Ancestry', 'https://www.ancestry.com/', NULL, '["ancestry.com","ancestry.co.uk","ancestry.ca","ancestry.com.au","ancestry.de","ancestrylibrary.com"]', 'The largest commercial collection: censuses, vital, church, military, immigration and directory records, plus user trees, worldwide and strongest for the US and UK.', '["census","vital","church","military","immigration","newspapers","compiled-trees"]', 'subscription', 'original-images', 'No public API; its terms forbid automated access.', 'Agents can''t sign in here. Log the search as inconclusive and add a to-do for the owner naming the exact collection and search terms. User trees are compiled: leads, not sources.', 1, 340, 'seed', '2026-11-15T00:00:00.000Z', '2026-11-15T00:00:00.000Z'),
  ('myheritage', 'MyHeritage', 'https://www.myheritage.com/', NULL, '["myheritage.com"]', 'Commercial records and user trees, strongest for Europe, Scandinavia and Israel; record matches and newspaper collections.', '["census","vital","church","newspapers","compiled-trees"]', 'subscription', 'original-images', 'No public API for records; its terms forbid automated access.', 'Agents can''t sign in here. Log as inconclusive and add a to-do for the owner with the collection to check.', 1, 350, 'seed', '2026-11-15T00:00:00.000Z', '2026-11-15T00:00:00.000Z'),
  ('findmypast', 'Findmypast', 'https://www.findmypast.co.uk/', NULL, '["findmypast.co.uk","findmypast.com","findmypast.ie","findmypast.com.au"]', 'Commercial records strongest for the UK and Ireland: parish registers, censuses including 1921, military records and the British Newspaper Archive.', '["census","church","military","newspapers"]', 'subscription', 'original-images', 'No public API; its terms forbid automated access.', 'Agents can''t sign in here. Free index searches may show a little; transcripts and images need a subscription. Log as inconclusive with a to-do for the owner.', 1, 360, 'seed', '2026-11-15T00:00:00.000Z', '2026-11-15T00:00:00.000Z'),
  ('newspapers-com', 'Newspapers.com', 'https://www.newspapers.com/', NULL, '["newspapers.com"]', 'Commercial archive of digitised newspapers, mostly United States, 1700s to the present.', '["newspapers"]', 'subscription', 'original-images', 'No public API; its terms forbid automated access.', 'Agents can''t sign in here. Search-result snippets are not a source. Add a to-do for the owner naming the paper and date range.', 1, 370, 'seed', '2026-11-15T00:00:00.000Z', '2026-11-15T00:00:00.000Z'),
  ('fold3', 'Fold3', 'https://www.fold3.com/', NULL, '["fold3.com"]', 'Commercial military records, mostly United States: service and pension files, draft cards, unit records.', '["military"]', 'subscription', 'original-images', 'No public API; its terms forbid automated access.', 'Agents can''t sign in here. Log as inconclusive and add a to-do for the owner with the exact collection.', 1, 380, 'seed', '2026-11-15T00:00:00.000Z', '2026-11-15T00:00:00.000Z');
