-- Research sites (the shared list every research agent works from) and their optional credentials. Additive only.
-- Managed by the owner in Admin → Research sites; the seed below is a starting list of broadly useful, international
-- genealogy resources. Credentials are encrypted (AES-GCM, key in the SITE_CREDENTIALS_KEY secret) and kept in their
-- own table, which list queries never read.
CREATE TABLE research_sites (
  id TEXT PRIMARY KEY,
  name TEXT NOT NULL,
  url TEXT NOT NULL,                        -- home page
  search_url TEXT,                          -- optional template with {given} {surname} {birth_year} {place}
  domains TEXT NOT NULL DEFAULT '[]',       -- JSON list of hostnames the site covers (matched against fetched URLs)
  coverage TEXT NOT NULL DEFAULT '',        -- regions, eras and record types, in words
  record_types TEXT NOT NULL DEFAULT '[]',  -- JSON list: census, vital, church, military, immigration, newspapers, ...
  access TEXT NOT NULL DEFAULT 'open',      -- open | free-account | subscription | institution
  source_quality TEXT NOT NULL DEFAULT 'indexes', -- original-images | indexes | compiled
  api TEXT NOT NULL DEFAULT '',             -- whether it has an official API, and where
  agent_notes TEXT NOT NULL DEFAULT '',     -- how to search it well, and its quirks
  enabled INTEGER NOT NULL DEFAULT 1,
  sort INTEGER NOT NULL DEFAULT 0,
  created_by TEXT NOT NULL,
  created_at TEXT NOT NULL,
  updated_at TEXT NOT NULL,
  updated_by TEXT
);

-- One credential per site, in its own table so list queries never touch it. `secret` is base64(iv || AES-GCM
-- ciphertext) of a JSON object, bound to the site id. No API ever returns it.
CREATE TABLE research_site_credentials (
  site_id TEXT PRIMARY KEY,
  kind TEXT NOT NULL,                       -- header | query | basic
  secret TEXT NOT NULL,
  updated_at TEXT NOT NULL,
  updated_by TEXT NOT NULL
);

-- 38 sites

UPDATE meta SET value = '10' WHERE key = 'schema' AND CAST(value AS INTEGER) < 10;
